import numpy as np


def most_similar_index(documents, query):
    if len(documents) == 0 or len(query) == 0:
        return -1
    q = np.array(query, dtype=float)
    if np.linalg.norm(q) == 0:
        return -1
    scores = []
    for i, doc in enumerate(documents):
        d = np.array(doc, dtype=float)
        norm = np.linalg.norm(d)
        if norm == 0:
            continue
        scores.append((float(d @ q) / float(norm * np.linalg.norm(q)), -i))
    if not scores:
        return -1
    return -max(scores)[1]
